import{_ as t,o as s,c as e,a3 as n}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"双仓架构","description":"","frontmatter":{},"headers":[],"relativePath":"docs/guide/dual-repo-architecture.md","filePath":"docs/guide/dual-repo-architecture.md"}'),i={name:"docs/guide/dual-repo-architecture.md"};function l(d,a,p,o,r,c){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="双仓架构" tabindex="-1">双仓架构 <a class="header-anchor" href="#双仓架构" aria-label="Permalink to &quot;双仓架构&quot;">​</a></h1><h2 id="为什么需要双仓架构" tabindex="-1">为什么需要双仓架构？ <a class="header-anchor" href="#为什么需要双仓架构" aria-label="Permalink to &quot;为什么需要双仓架构？&quot;">​</a></h2><p>常见的需求矛盾：</p><ul><li>想要文档内容开源协作 → 需要公开仓库</li><li>想要保护主题设计 → 不希望样式代码开源</li></ul><p>传统方案只能二选一。双仓架构解决了这个矛盾。</p><h2 id="架构原理" tabindex="-1">架构原理 <a class="header-anchor" href="#架构原理" aria-label="Permalink to &quot;架构原理&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                   公开仓库 (Public)                  │</span></span>
<span class="line"><span>│  github.com/hpp-bot/vite-docs                       │</span></span>
<span class="line"><span>│  ├─ docs/           ← 所有人的协作内容              │</span></span>
<span class="line"><span>│  ├─ .vitepress/theme/  ← 空壳（由CI填充）           │</span></span>
<span class="line"><span>│  └─ .github/workflows/  ← CI/CD 定义               │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                          ↓ git pull (CI中)</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  私有仓库 (Private)                   │</span></span>
<span class="line"><span>│  github.com/hpp-bot/vite-docs-theme                 │</span></span>
<span class="line"><span>│  └─ .vitepress/theme/  ← 主题样式，仅作者可访问     │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                          ↓ vitepress build</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                 GitHub Pages (公开访问)              │</span></span>
<span class="line"><span>│  hpp-bot.github.io/vite-docs/                      │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="两个仓库的职责划分" tabindex="-1">两个仓库的职责划分 <a class="header-anchor" href="#两个仓库的职责划分" aria-label="Permalink to &quot;两个仓库的职责划分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>职责</th><th>公开仓库</th><th>私有仓库</th></tr></thead><tbody><tr><td>Markdown 文档内容</td><td>✅</td><td>❌</td></tr><tr><td>前端 UI 框架代码</td><td>✅</td><td>❌</td></tr><tr><td>CI/CD 配置</td><td>✅</td><td>❌</td></tr><tr><td>CSS 主题样式</td><td>❌</td><td>✅</td></tr><tr><td>自定义 Vue 组件</td><td>❌</td><td>✅</td></tr><tr><td>Git 访问权限</td><td>所有人</td><td>仅作者</td></tr><tr><td>GitHub Pages 部署</td><td>✅ 构建来源</td><td>❌</td></tr></tbody></table><h2 id="同步机制" tabindex="-1">同步机制 <a class="header-anchor" href="#同步机制" aria-label="Permalink to &quot;同步机制&quot;">​</a></h2><p>使用 GitHub Actions 实现自动同步：</p><ol><li>当私有仓库推送新主题时，触发 <code>sync-theme.yml</code> workflow</li><li>Workflow 使用 PAT clone 私有仓库</li><li>将 <code>.vitepress/theme/</code> 复制到公开仓库对应位置</li><li>提交并推送到公开仓库</li><li>公开仓库的 <code>deploy.yml</code> 捕获推送事件</li><li>执行 <code>vitepress build</code> 构建并部署到 GitHub Pages</li></ol><h2 id="安全性考量" tabindex="-1">安全性考量 <a class="header-anchor" href="#安全性考量" aria-label="Permalink to &quot;安全性考量&quot;">​</a></h2><ul><li>PAT 存储在公开仓库的 GitHub Secrets 中，只有 Actions 可以访问</li><li>私有仓库的权限设置为 minimum required（repo scope）</li><li>公开仓库中的 <code>.gitignore</code> 不包含敏感信息</li></ul><h2 id="局限性" tabindex="-1">局限性 <a class="header-anchor" href="#局限性" aria-label="Permalink to &quot;局限性&quot;">​</a></h2><ul><li>主题变更需要约 1-2 分钟才能反映到线上</li><li>需要维护两个仓库的同步状态</li><li>首次部署需要手动触发一次 workflow</li></ul>`,16)])])}const b=t(i,[["render",l]]);export{u as __pageData,b as default};
